create table RB_TRAN_CONTROL_HIST (CHANNEL_SEQ_NO VARCHAR(60) not null  ,CHANNEL_DATE TIMESTAMP(3) not null  ,SOURCE_TYPE VARCHAR(10) not null  ,SUB_SEQ_NO VARCHAR(60) not null  ,BUSI_SUB_CLASS VARCHAR(10) null  ,CLIENT_NO VARCHAR(22) null  ,TRAN_DATE TIMESTAMP(3) not null  ,TRAN_BRANCH VARCHAR(30) null  ,TRAN_EVENT_TYPE VARCHAR(20) null  ,TRAN_DESC VARCHAR(200) null  ,REFERENCE VARCHAR(60) null  ,ONLINE_TRAN_STATUS VARCHAR(1) null  ,MESSAGE_TYPE VARCHAR(10) null  ,MESSAGE_CODE VARCHAR(10) null  ,SERVICE_CODE VARCHAR(20) null  ,SOURCE_MODULE VARCHAR(2) null  ,TRAN_TIMESTAMP VARCHAR(26) null  ,COMPANY VARCHAR(20) null  ,CUSTOMER_SEQ_NO VARCHAR(60) null  ,LAST_CHANGE_DATE TIMESTAMP(3) null  ,CREATE_TIMESTAMP VARCHAR(26) null  ,TRAN_CODE VARCHAR(50) null  ,TAE_TRADE_MODE VARCHAR(10) null  ,DR_CR_FLAG VARCHAR(3) null  ,TAE_FLAG VARCHAR(1) null  , primary key(CHANNEL_SEQ_NO,CHANNEL_DATE,SOURCE_TYPE,SUB_SEQ_NO,TRAN_DATE));